const BASE=["불정령","물정령","대지정령","바람정령","번개정령","나무정령","빛정령","어둠정령","오크","언데드","뱀파이어","수인","인간","천사","악마"];
// 시간정령: 희귀 등장(낮은 확률) + 코인 상점 구매 전용, BASE 풀과 별도 관리
const RARE_BASE=["시간정령"];
// 클리어 횟수별 개방 속성
const UNLOCK_ELEMENTS=(cc)=>{
  // 기본: 영웅까지 조합 가능하도록 핵심 속성 포함
  const els=["불정령","물정령","대지정령","바람정령","인간",
             "어둠정령","나무정령","오크","언데드","뱀파이어","수인"];
  if(cc>=1)els.push("번개정령","빛정령","천사","악마");
  return els;
};
// 클리어 횟수별 개방 등급
const UNLOCK_GRADES=(cc)=>{
  const grades=["노말","고급","영웅"];
  if(cc>=1)grades.push("전설");
  if(cc>=3)grades.push("신화");
  if(cc>=5)grades.push("불멸");
  return grades;
};
// 클리어 횟수별 개방 난이도
const UNLOCK_DIFF=(cc)=>{
  const diffs=["easy"];
  if(cc>=1)diffs.push("normal");
  if(cc>=5)diffs.push("hard");
  return diffs;
};
