// 등급별 사거리 보정
const GRADE_RANGE_BONUS={"노말":0,"고급":0.2,"영웅":0.4,"전설":0.6,"신화":0.8,"불멸":1.2};
const getRange=(el,grade)=>{
  const base=EL_RANGE[el]||3.0;
  const bonus=GRADE_RANGE_BONUS[grade]||0;
  return Math.min(base+bonus, 7.0);
};

